let saved,checks;try{saved=JSON.parse(localStorage.getItem('ve-saved')||'[]');checks=JSON.parse(localStorage.getItem('ve-checks')||'{}')}catch{saved=[];checks={}}if(!Array.isArray(saved))saved=[];if(!checks||typeof checks!=='object')checks={};
