const concepts=[...patternRows.map((r,i)=>({id:'p'+i,name:r[0],cat:r[1],level:r[2],desc:r[3],example:r[4],caution:r[5],prompt:r[6],kind:'patterns'})),...principles.map((r,i)=>({id:'d'+i,name:r[0],cat:r[1],level:r[2],desc:r[3],example:r[4],caution:r[5],prompt:`Review this project for ${r[0]}. Identify a concrete problem first. Suggest the smallest justified change, explain its tradeoffs, and preserve acceptance criteria.`,kind:'principles'})),...architecture.map((r,i)=>({id:'a'+i,name:r[0],cat:r[1],level:r[2],desc:r[3],example:r[4],caution:r[5],prompt:`Evaluate ${r[0]} for this project. State the problem it solves, operational costs, simpler alternatives and evidence that would justify it. Do not implement until the tradeoff is clear.`,kind:'architecture'}))];
let page='overview',designTab='patterns',designFilter='All',designQuery='',complianceFilter='All',pipe=0,risk='prototype',scenario='retry';
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Copied to clipboard')}catch{const ta=document.createElement('textarea');ta.value=t;document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?'Copied to clipboard':'Copy unavailable. Select and copy the text manually.')}}
function head(n,title,desc){return `<div class="intro"><div><div class="eyebrow">${n==='+'?'THE REAL-WORLD BRIDGE':n==='REF'?'REFERENCE NOTES':'FIELD SHEET '+n}</div><h1>${title}</h1><p>${desc}</p></div><span class="section-number">${n==='+'?'APPLIED THINKING':n==='REF'?'REVIEWED 26 OCT 2026':'SHEET '+n+' / 05'}</span></div>`}
function svg(k){return `<svg viewBox="0 0 32 32" aria-hidden="true">${icons[k]||icons.design}</svg>`}
function nav(){
  const item=p=>`<a href="#${p[0]}" class="nav-item ${page===p[0]?'active':''}" ${page===p[0]?'aria-current="page"':''}><span class="nav-num">${p[1]}</span><b>${p[2]}</b>${page===p[0]?'<span class="nav-arrow" aria-hidden="true">↗</span>':''}</a>`;
  const support=pages.slice(6),supportActive=support.some(p=>p[0]===page);
  $('#nav').innerHTML=item(pages[0])+'<div class="nav-label">THE FIVE FIELD SHEETS</div>'+pages.slice(1,6).map(item).join('')+`<details class="nav-tools" ${supportActive?'open':''}><summary>Tools & references</summary>${support.map(item).join('')}</details>`;
  $('#crumb').textContent=(pages.find(p=>p[0]===page)||pages[0])[2].toUpperCase();
}
function overview(){const sheets=[['design','01','Software design','Choose clear boundaries and useful patterns. Give your AI a design, not just a feature request.','57 CONCEPTS · PYTHON + JAVASCRIPT'],['qa','02','Testing & QA','Turn “it seems to work” into evidence. Test the rules, the boundaries and the failure paths.','12 METHODS · PAIRED CODE EXAMPLES'],['compliance','03','Compliance','Find the obligations that follow your domain, data and users. Understand what each one proves.','15 COMPLIANCE & QUALITY REFERENCES'],['stacks','04','Tech stacks','Start with the problem. Choose the fewest tools that meet your real constraints.','INTERACTIVE STACK SELECTOR'],['sdlc','05','The lifecycle','Make small changes deliberately. Plan, build, verify, release and learn with a repeatable process.','7 APPROACHES · ONE WORKFLOW'],['risk','↗','Could you build an ATM?','Explore where AI helps, where the risks change, and where specialist assurance is essential.','FROM PROTOTYPE TO HIGH ASSURANCE']];return `<section class="hero"><div><div class="eyebrow">A FIELD GUIDE FOR AI-ASSISTED BUILDERS</div><h1>Keep the vibe.<br><em>Build with discipline.</em></h1><p>You don’t need to memorise syntax to make better software decisions. You do need to know what to ask, what to check, and when to bring in an expert.</p><div class="hero-actions"><a class="btn primary" href="#design">Explore the field sheets <span>↗</span></a><a class="btn" href="#stacks">Choose a tech stack <span>→</span></a></div></div><div class="hero-visual" aria-label="Engineering adds explicit requirements, boundaries and independent checks between an idea and a dependable product"><div class="visual-label"><span>THE GAP WE’RE CLOSING</span><span>FIG. 01</span></div><div class="diagram-row"><div class="node">An idea<small>WHAT YOU WANT</small></div><span class="diagram-arrow">→</span><div class="node">AI-generated code<small>A STARTING POINT</small></div></div><div class="diagram-line"><span>↓</span><span>↓</span></div><div class="diagram-row middle"><div class="node">Clear requirements</div><div class="node">Design boundaries</div></div><div class="diagram-row middle"><div class="node">Independent checks</div><div class="node">Operational care</div></div><div class="diagram-line"><span>↓</span></div><div class="diagram-row"><div class="node dark">A product you can explain, test & maintain<small>ENGINEERING IS THE BRIDGE</small></div></div><div class="visual-caption">AI CAN WRITE THE CODE. ACCOUNTABILITY STAYS WITH PEOPLE.</div></div></section><div class="stat-strip"><div class="stat"><b>05</b><span>connected<br>field sheets</span></div><div class="stat"><b>23</b><span>classic design<br>patterns explained</span></div><div class="stat"><b>20</b><span>practical design<br>principles</span></div><div class="stat"><b>∞</b><span>syntax to outsource.<br>judgment to develop.</span></div></div><div class="section-head"><div><h2>Your engineering toolkit</h2><p>Pick the decision in front of you. Every sheet is a working reference.</p></div><span class="tiny">LEARN → APPLY → VERIFY</span></div><div class="sheets-grid">${sheets.map(r=>`<a class="sheet ${r[0]==='risk'?'special':''}" href="#${r[0]}"><div class="sheet-top"><span class="sheet-num">${r[1]} / FIELD SHEET</span>${svg(r[0])}</div><h3>${r[2]}</h3><p>${r[3]}</p><div class="sheet-foot"><span>${r[4]}</span><span>↗</span></div></a>`).join('')}</div><div class="quote-panel"><div><div class="eyebrow">THE MINDSET SHIFT</div><h3>From “make it work”<br>to “show why it works.”</h3></div><div><p>A generated feature is a hypothesis. Requirements, review, tests and real operating feedback provide evidence. You can delegate typing; you still need to own the decisions.</p><div class="mini-steps"><span>DEFINE THE OUTCOME</span><span>BOUND THE CHANGE</span><span>VERIFY THE RESULT</span></div></div></div>`}
function conceptCard(c){return `<article class="concept-card design-card"><div class="card-meta"><span class="tag ${c.cat==='Creational'?'orange':''}">${esc(c.cat)}</span><span class="level">${esc(c.level)}</span></div><h3 aria-label="${esc(c.name)}"><button class="design-card-open" data-detail="${c.id}" aria-label="Open ${esc(c.name)}" aria-describedby="concept-desc-${c.id}">${esc(c.name)}</button></h3><p id="concept-desc-${c.id}">${esc(c.desc)}</p><div class="card-actions"><span class="design-card-link" aria-hidden="true">Explore guide <span>↗</span></span><button class="save ${saved.includes(c.id)?'active':''}" data-save="${c.id}" aria-label="${saved.includes(c.id)?'Unsave':'Save'} ${esc(c.name)}" aria-pressed="${saved.includes(c.id)}">${saved.includes(c.id)?'★':'☆'}</button></div></article>`}
function design(){return head('01','Software design','Find a concept, see when it fits, and compare a small Python or JavaScript example.')+`<details class="intro-explainer"><summary>How principles, patterns and architecture differ</summary><div class="level-map"><div><span class="tiny">01 / SYSTEM</span><b>Architecture</b><p>Deployable units, business boundaries and data ownership.</p></div><div><span class="tiny">02 / MODULE</span><b>Design principles</b><p>Responsibilities, dependencies and coherent contracts.</p></div><div><span class="tiny">03 / COMPONENT</span><b>Design patterns</b><p>Creation, structure and collaboration of objects.</p></div><div><span class="tiny">04 / IMPLEMENTATION</span><b>Syntax & libraries</b><p>AI helps write it. Someone must still understand and review it.</p></div></div></details><div class="tabs" role="tablist" aria-label="Design catalog"><button role="tab" tabindex="${designTab==='patterns'?'0':'-1'}" aria-selected="${designTab==='patterns'}" class="tab ${designTab==='patterns'?'active':''}" data-tab="patterns">Classic patterns <span>23</span></button><button role="tab" tabindex="${designTab==='principles'?'0':'-1'}" aria-selected="${designTab==='principles'}" class="tab ${designTab==='principles'?'active':''}" data-tab="principles">Principles <span>20</span></button><button role="tab" tabindex="${designTab==='architecture'?'0':'-1'}" aria-selected="${designTab==='architecture'}" class="tab ${designTab==='architecture'?'active':''}" data-tab="architecture">Architecture & resilience <span>14</span></button></div><div id="design-body"></div><div class="notice"><b>Patterns are choices, not a checklist.</b> Open any concept for when-to-use guidance, pitfalls, Python and JavaScript examples, expected output and limitations.  These are all 23 classic Gang of Four patterns, plus a selected set of broader patterns and principles. There is no finite, universally accepted list of every software pattern. Labels show typical scope, not strict limits; many ideas work across several levels.</div><details><summary>Not sure which pattern to ask for? Start with the change.</summary><div><div class="table-wrap"><table><thead><tr><th>The problem</th><th>Consider</th><th>First question</th></tr></thead><tbody><tr><td>Several algorithms for one job</td><td>Strategy</td><td>Will these algorithms actually vary independently?</td></tr><tr><td>A third-party API does not fit yours</td><td>Adapter</td><td>Which external guarantees must remain visible?</td></tr><tr><td>Rules change with lifecycle status</td><td>State</td><td>What transitions are legal, including failure states?</td></tr><tr><td>Several local listeners need an update</td><td>Observer</td><td>Who subscribes, unsubscribes and handles listener errors?</td></tr><tr><td>Object creation varies by subtype</td><td>Factory Method</td><td>Would a simple factory function be sufficient?</td></tr><tr><td>External requests are duplicated</td><td>Idempotency + transaction design</td><td>Where is the durable operation key and result stored?</td></tr></tbody></table></div></div></details>`}
function renderDesignBody(){const rows=concepts.filter(c=>c.kind===designTab);const cats=['All',...new Set(rows.map(c=>c.cat))];const filtered=rows.filter(c=>(designFilter==='All'||c.cat===designFilter)&&[c.name,c.cat,c.desc,c.example,c.level].join(' ').toLowerCase().includes(designQuery.toLowerCase()));$('#design-body').innerHTML=`<div class="filter-row"><div class="chips" aria-label="Category filter">${cats.map(c=>`<button class="chip ${c===designFilter?'active':''}" data-filter="${esc(c)}" aria-pressed="${c===designFilter}">${esc(c)}</button>`).join('')}</div><label class="inline-search"><span>⌕</span><input id="design-query" aria-label="Filter concepts" value="${esc(designQuery)}" placeholder="Filter concepts…"></label></div><div class="result-count" aria-live="polite">${filtered.length} CONCEPTS / SELECT A CARD TO GO DEEPER</div><div class="card-grid design-cards">${filtered.map(conceptCard).join('')||'<div class="empty">No concepts match. Try a broader search.</div>'}</div>`}
const pipeData=[['Local change','Define & verify','Before opening a pull request','Write the acceptance example first. Make one bounded change, run focused tests and inspect the diff. Keep work in version control. A separate branch preserves a reviewable change.'],['Pull request','Automated CI','Make failure visible','Run install from a lockfile, type checks, tests, build, secret scanning and dependency/security checks. Protect the main branch with required checks and review. A YAML file alone does not enforce branch protection.'],['Review','Human judgment','Review the assumptions','A reviewer checks requirements, design boundaries, error handling and test oracles. AI can suggest issues; the accountable reviewer must understand the change. Untrusted pull requests must not receive deployment secrets.'],['Staging','Production-like checks','Test the integrated artifact','Build once and promote the same immutable artifact. Test critical journeys, configuration, migrations, permissions and operational behaviour in a safe environment with synthetic data.'],['Release','Controlled rollout','Choose your CD meaning','Continuous delivery keeps a releasable build with a release decision. Continuous deployment automatically releases qualifying builds. Choose approval and rollout gates by risk; prepare rollback or roll-forward.'],['Observe','Learn & recover','The lifecycle keeps going','Watch errors, latency, availability and business outcomes. Assign alert ownership, verify restore procedures and handle vulnerability reports. Feed incidents and user feedback into the next small change.']];
const yaml=`# Illustrative Node project CI. Adapt scripts and runtime to your repo.
# This checks changes; it does not deploy production.
name: Verify
on: [push, pull_request]
permissions:
  contents: read
jobs:
  verify:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      # For stronger supply-chain control, pin verified actions to full SHAs.
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version-file: '.nvmrc'
          cache: npm
      - run: npm ci
      - run: npm run typecheck
      - run: npm test -- --run
      - run: npm run build
# Required repo setup:
# .nvmrc: a supported Node release; package-lock.json committed.
# typecheck script: tsc --noEmit; test script: vitest; build: your build tool.
# Add security/dependency/secret scans and appropriate integration/E2E jobs.
# Configure branch protection and deployment environment gates separately.`;
function qa(){return head('02','Replace confidence with evidence.','Quality assurance prevents mistakes in the process. Testing looks for failures in the product. You need both—and independent expectations for what “correct” means.')+`<div class="two-col"><div class="panel"><div class="eyebrow">THE TESTING SHAPE</div><h2>Test at the right boundary.</h2><div class="steps-list"><div class="step-line"><b>Many fast, focused checks</b><span>Business rules, invalid input, boundaries and invariants.</span></div><div class="step-line"><b>Real integration checks</b><span>Database constraints, API contracts and external-system behaviour.</span></div><div class="step-line"><b>A few critical end-to-end journeys</b><span>Prove valuable flows work through the real application.</span></div></div></div><div class="panel dark"><div class="eyebrow">THE ORACLE PROBLEM</div><h2>Who decided the expected answer?</h2><p>If AI writes the function and copies its reasoning into the test, both can agree on the same wrong result.</p><p>Use requirements, trusted reference calculations, independently derived examples and domain review. A second AI reviewer is useful input, not independent proof.</p><a href="#checklist" class="btn" style="border-color:#879c79;color:#eaf2df">Build an evidence checklist ↗</a></div></div><div class="section-head"><div><h2>A practical testing toolkit</h2><p>Tool names are examples. Match the method to the risk and boundary.</p></div></div><div class="card-grid">${tests.map((r,i)=>`<article class="concept-card"><div class="card-meta"><span class="tag">${r[1]}</span><span class="level">${String(i+1).padStart(2,'0')}</span></div><h3>${r[0]}</h3><p><b>${r[2]}</b></p><p>${r[3]}</p><details><summary>Tools & limits</summary><div><p>${r[4]}</p><p>${r[5]}</p></div></details><div class="card-actions"><button class="text-btn" data-example="t${i}">Use guide & code examples ↗</button></div></article>`).join('')}</div><div class="section-head"><div><h2>From a change to a safe release</h2><p>Select a stage to see its purpose and required evidence.</p></div><span class="tiny">CI/CD WALKTHROUGH</span></div><div class="pipeline">${pipeData.map((r,i)=>`<button class="pipe-step ${i===pipe?'active':''}" data-pipe="${i}" aria-pressed="${i===pipe}"><span>0${i+1}</span><b>${r[0]}</b></button>`).join('')}</div><div id="pipe-detail"></div><details><summary>CI starter: a readable GitHub Actions example</summary><div><p>Illustrative configuration for a TypeScript / Vitest repository. It is not the deployment configuration for this guide. Verify supported runtime and action versions before adopting it.</p><button class="btn small" id="copy-yaml">Copy workflow</button><pre>${esc(yaml)}</pre><p>Install TypeScript and Vitest in the project, define the named scripts, commit the npm lockfile and set a supported Node version in <code>.nvmrc</code>. Add security scanning, migration tests and browser tests as needed. Keep deployment credentials out of pull-request jobs; use short-lived deployment identity where available.</p></div></details><div class="notice"><b>QA outside the tests:</b> acceptance criteria, design review, small diffs, coding conventions, reproducible builds, controlled environments, defect triage, change records, production observability and incident learning. Coverage percentages alone do not establish quality.</div>`}
function renderPipe(){const r=pipeData[pipe];$('#pipe-detail').innerHTML=`<div class="pipe-detail"><div><div class="tiny">${r[1]}</div><h3>${r[2]}</h3></div><p>${r[3]}</p></div>`;document.querySelectorAll('[data-pipe]').forEach(b=>{b.classList.toggle('active',+b.dataset.pipe===pipe);b.setAttribute('aria-pressed',+b.dataset.pipe===pipe)})}
function compliancePage(){return head('03','Know what applies. Then prove it.','“Compliant” is not a generic software quality badge. Applicability follows the product, organisation, jurisdiction, contracts, data and consequences of failure.')+`<div class="notice coral"><b>Start with scope.</b> This is an orientation map, not a legal determination or exhaustive compliance register. Laws are jurisdiction-specific; international standards may become required through law, contract or an assurance scheme. Confirm applicable versions and obligations with qualified owners.</div><div class="filter-row"><div class="chips" aria-label="Compliance domain filter">${['All','General SaaS','Personal data','Payments / ATM','Healthcare','Accessibility','Functional safety','Quality & lifecycle'].map(c=>`<button class="chip ${c===complianceFilter?'active':''}" data-domain="${c}" aria-pressed="${c===complianceFilter}">${c}</button>`).join('')}</div></div><div id="compliance-body"></div><div class="section-head"><h2>The evidence chain</h2></div><div class="delivery-loop">${[['01','Scope','What system, people, data and jurisdictions are included?'],['02','Controls','Which obligations apply, and who owns each one?'],['03','Evidence','Link requirements to designs, tests, records and operation.'],['04','Assessment','Use the required independent review or validation process.']].map(r=>`<div class="loop-cell"><span>${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p></div>`).join('')}</div><div class="notice">Also investigate local privacy and consumer laws, financial regulation, open-source licences, contractual data residency, sector requirements and AI-specific obligations when relevant. A secure cloud provider or a passed scanner does not transfer its compliance status to your application.</div>`}
function renderCompliance(){const rows=compliance.filter(r=>complianceFilter==='All'||r[2]===complianceFilter);$('#compliance-body').innerHTML=`<div class="result-count">${rows.length} REFERENCES IN THIS VIEW</div><div class="compliance-grid">${rows.map(r=>`<article class="compliance-card"><div class="card-meta"><span class="tag">${r[1]}</span><span class="level">${r[2]}</span></div><h3>${r[0]}</h3><p>${r[3]}</p><p class="labelled"><strong>WHEN TO INVESTIGATE</strong>${r[4]}</p><p class="labelled"><strong>WHAT EVIDENCE LOOKS LIKE</strong>${r[5]}</p><a href="${r[6]}" target="_blank" rel="noopener noreferrer">Official source ↗</a></article>`).join('')}</div>`}
function stacks(){return head('04','Pick for the problem, not the hype.','A tech stack is a set of cooperating tools. Start with users, data, deployment constraints and your team’s ability to operate it. There is no universally best stack.')+`<div class="stack-layout"><div class="panel"><div class="eyebrow">YOUR STARTING CONSTRAINTS</div><h2>What are you building?</h2><label class="field"><span>01 / PRIMARY PRODUCT</span><select id="stack-product"><option value="content">Content site / portfolio / documentation</option><option value="app" selected>Web app / dashboard / SaaS</option><option value="compute">Engineering calculations / data / AI</option><option value="mobile">Mobile app with device features</option><option value="desktop">Desktop / CAD companion</option><option value="embedded">Embedded / hard real-time / safety-related</option></select></label><label class="field"><span>02 / DATA & WORKLOAD</span><select id="stack-data"><option value="ordinary">Ordinary records and workflows</option><option value="relations">Related records / transactions / reporting</option><option value="offline">Offline-first or local-only</option><option value="realtime">Live updates and background jobs</option></select></label><label class="field"><span>03 / CONSEQUENCES OF FAILURE</span><select id="stack-risk"><option value="low">Learning / low-impact internal use</option><option value="business" selected>Business operations / personal data</option><option value="high">Payments / medical / safety / regulated</option></select></label><p style="font-size:11px">This is a transparent starting heuristic, not a benchmark or certification. Validate the recommendation against deployment constraints, team skills and a small proof of concept.</p></div><div id="stack-result" aria-live="polite"></div></div><div class="section-head"><div><h2>Add a capability only when you need it</h2><p>Examples to investigate—not a shopping list. Check supported versions, licences, hosting and maintenance.</p></div></div><div class="table-wrap"><table><thead><tr><th>Need</th><th>Candidate tools / approach</th><th>Decision rule & cost</th></tr></thead><tbody>${[
['UI & styling','React, Vue or Svelte; CSS / Tailwind; accessible component primitives','A simple page may only need HTML, CSS and JavaScript. Audit keyboard and screen-reader behaviour.'],
['Web framework','Next.js / React Router for React; Django for a Python-led product','Use integrated routing/rendering when useful; do not combine overlapping frameworks.'],
['Python APIs / calculations','FastAPI + Pydantic; NumPy / SciPy for numerical work','Separate authoritative calculations from UI. Specify units, validity limits, precision and reference cases.'],
['Database','PostgreSQL for relational data; SQLite for local or modest single-writer workloads','Choose using relationships, consistency and workload. Document databases fit document-shaped access; not a default shortcut.'],
['Data access','Prisma / Drizzle (TypeScript), SQLAlchemy (Python)','Migrations and constraints still need review. An ORM does not remove concurrency or query-performance issues.'],
['Authentication','Established identity provider or mature framework auth; OIDC where appropriate','Prefer supported solutions. You still own session configuration, authorisation and account recovery.'],
['Forms & validation','React Hook Form + Zod (React); Pydantic (Python API)','Client validation improves experience; validate and authorise again on the server.'],
['Server / client state','TanStack Query for remote data; component state first for local UI','Add a global store such as Zustand only for actual shared-state complexity.'],
['Live updates','Server-Sent Events for one-way updates; WebSockets for bidirectional interaction','Start with polling if adequate. Plan reconnection, authorisation, ordering and duplicate messages.'],
['Background work','Celery / RQ (Python), BullMQ (Node), managed queues','Use for slow or retryable tasks. Define idempotency, timeouts, dead-letter handling and observability.'],
['Search & retrieval','Database full-text search first; pgvector or dedicated retrieval when justified','Measure retrieval quality, permissions and freshness. Vectors alone are not a trustworthy AI system.'],
['Files & uploads','Object storage with signed access and server-side validation','Plan size/type limits, malware handling, retention and access checks; never trust a filename.'],
['Charts / 3D','Chart.js / Apache ECharts; Three.js for interactive 3D','Choose for the actual visual need and performance budget. A game library is unnecessary for ordinary forms.'],
['Payments','A hosted flow from a supported payment provider','Avoid handling raw card data when unnecessary. Verify webhooks, server-side totals, idempotency and scope.'],
['Observability','OpenTelemetry; structured logs; an error tracker such as Sentry','Define alert ownership and privacy. More logs are not useful if nobody can act on them.']
].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div><div class="notice"><b>Default architectural bias:</b> use one deployable application with clear modules until independent scaling, team ownership or isolation requirements justify more. Add a cache, queue or microservice only after identifying the problem and its operating cost.</div>`}
let stackSelection={product:'app',data:'ordinary',risk:'business'};
function stackSpec(){const{product:p,data:d,risk:r}=stackSelection;const specs={content:['Content-first site','HTML/CSS or Astro','Usually none','Static files / CMS','Static hosting','The browser can display content without a custom backend. Add a CMS only for an actual editing workflow.','A static site does not need a database simply because databases are common.'],app:['A modular web application','React + a framework','Framework server or Django','PostgreSQL','Managed app + DB','A coherent framework handles common web concerns. Keep business modules explicit and deploy together to start.','A client-only dashboard may fit Vite + React with an existing API. A Python-first team may prefer Django.'],compute:['A calculation-focused application','React / Vite','Python + FastAPI','PostgreSQL or local files','App + Python service','Keep calculation rules in a tested Python library; expose a validated API and use the browser for inputs and results.','Two runtimes add deployment and contract work. Do not move trusted engineering logic into unverified generated UI code.'],mobile:['A cross-platform mobile product','React Native / Expo or Flutter','Supported backend API','Server DB + local cache','App stores + API','Use a mobile toolkit when device APIs, distribution or offline UX matter. Share contracts with the backend.','Validate native module support, background execution, store policies and offline synchronisation before committing.'],desktop:['A desktop / CAD companion','Host-native UI or Tauri / Electron','Local service or host API','SQLite / local files','Installer + update channel','Start with the CAD host’s supported extension API when integrating deeply. A web-based shell fits an independent companion.','Host compatibility, signing, IPC permissions and updates matter. A browser UI cannot directly call arbitrary CAD APIs.'],embedded:['Specialist-led system design','Hardware-appropriate UI','C / C++ / Rust + RTOS as justified','Device-appropriate storage','Controlled firmware process','Choose from timing, memory, hardware and assurance requirements. Prototype with AI, then use a qualified engineering process.','A web-stack recommendation is not suitable evidence for real-time or safety-related control. Toolchain qualification may need assessment.']};let s=[...specs[p]];let notes=[];if(d==='relations'){s[3]=p==='embedded'?'Assess hardware constraints':'PostgreSQL';notes.push('Related records and transactions favour a relational design. Define isolation, constraints and retry rules; a database alone does not make a workflow atomic.')}if(d==='offline'){s[3]=p==='mobile'||p==='desktop'?'SQLite + sync policy':p==='embedded'?'Device storage + integrity policy':'IndexedDB / local data';notes.push('Offline operation needs a conflict and sync policy. Browser data can be evicted; plan export, backup and recovery.')}if(d==='realtime'){notes.push('For live updates, choose SSE or WebSockets based on direction. Add a durable queue only for background tasks; account for reconnects, duplicates and delayed delivery.')}if(r==='high'){notes.push('High-consequence product: obtain specialist architecture, security and domain review before adoption. Establish the applicable assurance process and compliance scope.')}else if(r==='business'){notes.push('Business use: enforce server-side authorisation, protect personal data, test backup restore and define incident ownership.')}else{notes.push('Learning use: isolate demo data and credentials. Reassess the design before adding real users or sensitive information.')}if(p==='content'&&d!=='ordinary')notes.unshift('Your workload goes beyond a basic content site. Confirm whether it is actually an application before choosing static-only hosting.');return{s,notes}}
function renderStack(){const{s,notes}=stackSpec();$('#stack-result').innerHTML=`<div class="stack-result"><div class="eyebrow">A REASONED STARTING POINT</div><h2>${s[0]}</h2><p class="stack-reason">${s[5]}</p><div class="stack-chain">${[['FRONTEND',s[1]],['BACKEND',s[2]],['DATA',s[3]]].map(r=>`<div class="stack-node"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div><p class="tiny">OPERATING MODEL: ${s[4]}</p><div class="tradeoff"><b>The tradeoff</b><br>${s[6]}</div><div class="steps-list">${notes.map(t=>`<div class="step-line"><span>${t}</span></div>`).join('')}</div><button class="btn primary" id="copy-stack" style="margin-top:20px">Copy a stack-evaluation prompt ↗</button></div>`}
function sdlc(){return head('05','A lifecycle, not a lucky streak.','There is no single universally accepted SDLC for every product. Choose the delivery model for your risk and uncertainty; keep verification, security and operations inside the process.')+`<div class="panel dark"><div class="eyebrow">RECOMMENDED DEFAULT FOR ORDINARY WEB PRODUCTS</div><h2>Small increments. Explicit evidence. Continuous feedback.</h2><p>Use iterative delivery with a lightweight work board, small reviewed changes, automated CI and a controlled release process. Add DevSecOps practices throughout. Increase traceability and independent assurance when the consequences demand it.</p></div><div class="delivery-loop">${[['01','Define','State the user outcome, acceptance examples, constraints and risk.'],['02','Design & build','Choose boundaries. Make one small change with tests and a reviewable diff.'],['03','Verify & release','Check the artifact, approvals, migrations and recovery path before rollout.'],['04','Operate & learn','Watch outcomes, recover from failure and feed findings into the next loop.']].map(r=>`<div class="loop-cell"><span>${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p></div>`).join('')}</div><div class="section-head"><div><h2>Choose the approach deliberately</h2><p>Models, team frameworks and delivery practices are related, but they are not interchangeable.</p></div></div><label class="field"><span>YOUR PROJECT CONTEXT</span><select id="lifecycle-choice"><option value="product">Evolving web product / small team</option><option value="support">Maintenance / continuous incoming work</option><option value="stable">Stable specification / contractual handoffs</option><option value="assurance">Safety-related / regulated / high assurance</option><option value="unknown">Large technical uncertainties / expensive risks</option></select></label><div id="lifecycle-result" class="notice" aria-live="polite"></div><div class="method-list">${methods.map(r=>`<article class="method"><div class="card-meta"><span class="tag">${r[1]}</span></div><h3>${r[0]}</h3><p>${r[2]}</p><div class="fit"><b>When it fits</b><br>${r[3]}</div><p><b>Watch for:</b> ${r[4]}</p></article>`).join('')}</div><details><summary>A reusable AI task brief for each increment</summary><div><pre id="task-prompt">${esc(taskPrompt)}</pre><button class="btn small" id="copy-task">Copy task brief</button></div></details>`}
const taskPrompt=`Outcome: [user and measurable behaviour]
Context: [current architecture, deployment, supported versions]
Scope: [one bounded change] / Out of scope: [explicit exclusions]
Constraints: [security, privacy, performance, units, accessibility]
Acceptance examples: [inputs, expected outcomes, invalid/failure cases]
Before coding: identify unknowns, trust boundaries, simpler options and risks.
Implementation: preserve module boundaries; avoid unjustified dependencies.
Verification: derive tests from acceptance examples, not from the generated implementation.
Delivery: show the diff, checks run, evidence, unresolved risks and recovery impact.
Do not weaken tests or bypass controls to make checks pass. Flag uncertainty clearly.`;
function renderLifecycle(){const s=$('#lifecycle-choice').value;const r={product:'Use iterative / incremental delivery, with Kanban for a small team or Scrum if its full team framework fits. Add CI, reviews and controlled releases. This is a practical recommendation, not a universal industry mandate.',support:'Use Kanban-style flow with explicit priorities and work-in-progress limits. Make small changes and retain regression tests, release controls and incident feedback.',stable:'A predictive approach may fit agreed handoffs. Validate assumptions early and plan verification before implementation; change control still matters.',assurance:'Consider V-model-style verification planning within the applicable lifecycle and assurance requirements. Preserve bidirectional traceability and specialist review; iterative work can still occur inside controlled baselines.',unknown:'Use risk-driven iterations or a spiral approach: identify the most expensive uncertainty, run a bounded experiment, record evidence and decide before expanding.'};$('#lifecycle-result').textContent=r[s]}
const risks={prototype:['Learning / prototype','A safe place to practise the whole loop.','AI can help implement most of the experience when there are no real funds, personal records or connected hazardous devices.',['Use synthetic data and clearly mark simulated behaviour.','Keep the source in version control and state acceptance examples.','Test the rules, handle invalid inputs and review the diff.','Reassess the design before inviting real users.'],'You can close a substantial part of the process gap here by making your decisions and checks explicit.'],business:['Business product','You need an accountable operating process.','AI can accelerate delivery, but real users and business dependence introduce responsibilities beyond a working screen.',['Name an owner for architecture, security and incidents.','Verify authorisation, tenant isolation and data handling.','Use reliable CI, reviews, monitoring and restore tests.','Investigate legal and contractual obligations early.'],'A non-coder can lead requirements and acceptance. Production changes still need people capable of understanding and reviewing the implementation.'],atm:['ATM / payments','A cash dispenser is a distributed financial system.','A demo interface is achievable. An operational ATM needs bank-host integration, secure PIN handling, hardware coordination, reconciliation and specialised assurance.',['Use bank/device interfaces and approved payment hardware within their required scope.','Never treat a network timeout as proof that a debit or dispense did not happen.','Make transaction intent, durable records and reconciliation explicit.','Assess PCI DSS, PIN/PTS/HSM, bank/network rules and local regulation with specialists.'],'AI can support requirements, simulations, test drafts and reviewed implementation. This guide cannot make an unsupervised generated ATM safe or approved.'],safety:['Safety-related system','Start with hazards and assurance requirements.','Software that can contribute to injury needs a system-level safety process, qualified expertise and evidence proportionate to the hazard.',['Identify hazards and derive safety requirements before implementation.','Select the applicable sector standard and assessment process.','Maintain traceability from requirements to design and verification.','Assess tools, hardware interactions and independent review needs.'],'AI assistance may be usable within a controlled process. A plausible result or generated test suite is not a safety argument.']};
function riskPage(){return head('+','Could a vibe coder build an ATM?','You can close part of the gap by learning to specify, structure and verify software. The remaining gap is accountable expertise, domain knowledge and assurance—not simply more detailed prompts.')+`<div class="risk-layout"><div>${[['prototype','A learning prototype','Synthetic data, reversible consequences'],['business','A business application','Real users, records and operational dependence'],['atm','An ATM / payment system','Money, secure devices and bank integration'],['safety','A safety-related system','Potential physical harm or critical control']].map(r=>`<button class="risk-choice ${risk===r[0]?'active':''}" data-risk="${r[0]}" aria-pressed="${risk===r[0]}"><b>${r[1]}</b><span>${r[2]}</span></button>`).join('')}</div><div id="risk-output" aria-live="polite"></div></div><div class="section-head"><div><h2>One withdrawal. Several possible realities.</h2><p>A conceptual failure walkthrough, not a bank protocol or production state machine.</p></div></div><div class="panel"><p>Suppose a customer requests a withdrawal. The network or dispenser may fail between recording intent, obtaining authorisation and confirming cash movement. A timeout leaves uncertainty about what actually happened.</p><div class="scenario-buttons">${[['retry','Network times out'],['jam','Cash movement is uncertain'],['power','Power fails during the operation']].map(r=>`<button class="chip ${scenario===r[0]?'active':''}" data-scenario="${r[0]}" aria-pressed="${scenario===r[0]}">${r[1]}</button>`).join('')}</div><div class="scenario-out" id="scenario-output" aria-live="polite"></div><div class="mini-steps"><span>EXPLICIT STATES</span><span>DURABLE JOURNAL</span><span>IDEMPOTENT REQUESTS</span><span>RECONCILIATION</span><span>SPECIALIST ASSURANCE</span></div></div><div class="notice coral"><b>The limit of a cheat sheet:</b> principles improve judgment; they do not replace the ability to inspect code, reason about concurrency, validate security or satisfy domain-specific assurance. Bridge that remaining gap through learning and qualified collaborators.</div>`}
function renderRisk(){const r=risks[risk];$('#risk-output').innerHTML=`<div class="risk-output"><span class="risk-tag">${r[0]}</span><h2>${r[1]}</h2><p>${r[2]}</p><ul>${r[3].map(t=>`<li>${t}</li>`).join('')}</ul><div class="notice">${r[4]}</div></div>`;document.querySelectorAll('[data-risk]').forEach(b=>{b.classList.toggle('active',b.dataset.risk===risk);b.setAttribute('aria-pressed',b.dataset.risk===risk)})}
function renderScenario(){const texts={retry:'The host may have accepted the request even though the response never arrived. Preserve the transaction identifier and resolve its status through the defined host protocol. Blindly submitting a new request can duplicate an effect. Durable idempotency and reconciliation are required design topics.',jam:'“Dispense command accepted” is not the same as “cash reached the customer.” Device status, sensor/journal evidence and host records must be reconciled. Follow the bank/device-defined exception process; neither assuming success nor automatically refunding every uncertain case is safe.',power:'After restart, the UI cannot reconstruct reality from memory. Recover from a durable journal and reconcile the host transaction with dispenser evidence. An in-doubt state needs controlled resolution; do not silently mark it successful or retry it as a new withdrawal.'};$('#scenario-output').textContent=texts[scenario];document.querySelectorAll('[data-scenario]').forEach(b=>{b.classList.toggle('active',b.dataset.scenario===scenario);b.setAttribute('aria-pressed',b.dataset.scenario===scenario)})}
function checklistPage(){return head('REF','Before you ship, show the evidence.','Use this as a personal review aid. Checking an item records your judgment; it does not run a test, verify a document or certify readiness. Progress is saved in this browser.')+`<div class="check-header"><div><b id="check-count"></b><span> evidence items reviewed</span><div class="progress-track"><div id="check-progress"></div></div></div><button class="btn" id="copy-checklist">Copy review record ↗</button></div>${gateGroups.map(g=>`<section class="check-group"><h3>${g[0]}</h3>${g[1].map(r=>`<label class="check-row ${checks[r[0]]?'done':''}"><input type="checkbox" data-check="${r[0]}" ${checks[r[0]]?'checked':''}><span><b>${r[1]}</b><small>${r[2]}</small></span></label>`).join('')}</section>`).join('')}<div class="notice"><b>What the counter means:</b> items you marked as reviewed. It is not a risk score, test result or approval. Keep evidence links and named reviewers in your project’s own change record. Regulated or high-consequence systems require additional domain-specific controls.</div><div class="hero-actions"><button class="btn primary" id="print-checklist">Print this sheet ↗</button><button class="text-btn" id="reset-checklist">Reset review marks</button></div>`}
function updateChecks(){let n=gateGroups.flatMap(g=>g[1]).filter(r=>checks[r[0]]).length;$('#check-count').textContent=n+' / 10';$('#check-progress').style.width=(n*10)+'%';document.querySelectorAll('[data-check]').forEach(c=>c.closest('label').classList.toggle('done',c.checked))}
function savedPage(){return head('REF','Keep the useful ideas close.','Save concepts from the design sheets for a focused reference. Your selections stay in this browser; they do not sync between devices.')+`<div class="section-head"><h2>${saved.filter(id=>concepts.some(c=>c.id===id)).length} saved concepts</h2><a href="#design">Explore the catalog ↗</a></div><div class="card-grid design-cards">${concepts.filter(c=>saved.includes(c.id)).map(conceptCard).join('')||'<div class="empty">No saved concepts yet. Open Software design and select ☆ on an idea you want to keep.</div>'}</div>`}
function sourcePage(){return head('REF','Trace the advice back to its source.','Primary references for further study and for checking applicability. Plain-language explanations and stack recommendations are editorial guidance, not requirements quoted from these sources.')+`<div class="notice"><b>Scope & currency:</b> reviewed 26 October 2026. The design catalog contains the 23 GoF patterns, 20 selected principles and 14 architecture/data/resilience patterns. Compliance coverage is selective, not exhaustive. Tool examples are not ranked; confirm versions, support, pricing, licences and deployment compatibility before adoption.</div><div class="source-grid">${sources.map(r=>`<article class="source-card"><span class="tag">${r[0]}</span><a href="${r[2]}" target="_blank" rel="noopener noreferrer">${r[1]} ↗</a><p>${r[3]}</p></article>`).join('')}</div><div class="section-head"><div><h2>The language, in plain English</h2><p>Core terms you can use without learning a programming language.</p></div></div><div class="table-wrap"><table><thead><tr><th>Term</th><th>What it means</th></tr></thead><tbody>${glossary.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table></div><div class="section-head"><h2>How to use these sheets responsibly</h2></div><div class="two-col"><div class="panel"><h3>What this guide provides</h3><p>Vocabulary, decision prompts, examples, tradeoffs, an illustrative CI workflow and a practical process reference. It helps you ask better questions and spot missing work. Every design concept and testing method includes paired Python and JavaScript examples. The 134 self-contained snippets were executed in Python 3.12 and Node.js 24; four optional Playwright templates were syntax-checked, not executed with Playwright here. Architecture snippets are deliberately limited sketches, not deployable systems.</p></div><div class="panel"><h3>What remains project-specific</h3><p>Architecture validation, source-code review, numerical correctness, operational risk, legal applicability, certification and release approval. These require actual system evidence and qualified judgment.</p></div></div>`}
function showDetail(id){
  if(!concepts.some(c=>c.id===id))return;
  activeDetail={id,type:'concept'};activeDetailTab='guide';activeExampleId=id;
  renderDetail();if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
}
function render(){nav();const renders={overview,design,qa,compliance:compliancePage,stacks,sdlc,risk:riskPage,checklist:checklistPage,saved:savedPage,sources:sourcePage};$('#main').innerHTML=(renders[page]||overview)();if(page==='design')renderDesignBody();if(page==='qa')renderPipe();if(page==='compliance')renderCompliance();if(page==='stacks'){for(const[k,v]of Object.entries(stackSelection))$('#stack-'+k).value=v;renderStack()}if(page==='sdlc')renderLifecycle();if(page==='risk'){renderRisk();renderScenario()}if(page==='checklist')updateChecks();document.title=(pages.find(p=>p[0]===page)?.[2]||'Start here')+' — Vibe → Engineer'}
function route(){const target=location.hash.slice(1)||'overview';page=pages.some(p=>p[0]===target)?target:'overview';document.body.classList.remove('menu-open');render();window.scrollTo(0,0)}
function toggleSave(id){if(saved.includes(id))saved=saved.filter(s=>s!==id);else saved.push(id);persist();if(page==='design')renderDesignBody();if(page==='saved')render();if($('#detail-dialog').open)renderDetail();toast(saved.includes(id)?'Concept saved':'Concept removed')}
function openSearch(){$('#search-dialog').showModal();$('#search-input').value='';renderSearch('');$('#search-input').focus()}
function problemMatches(query){
  const rules=[
    [/(swap|switch|choose|different).*(algorithm|pricing|shipping)|(algorithm|pricing).*(vary|different)/,['p20']],
    [/(duplicate|twice|repeat).*(request|payment|charge|message|job)|(request|payment|charge|message|job).*(duplicate|twice|repeat)/,['d16']],
    [/retry|backoff/,['a12','d16']],
    [/(third.party|vendor|legacy).*(api|interface|integrat)|(api|interface).*(fit|match|compatib)/,['p5']],
    [/(state|status|lifecycle).*(rule|behav|transition)|legal transition/,['p19']],
    [/notify|listener|subscrib/,['p18']],
    [/(small|simple).*(app|project|team)|monolith|microservice/,['a0','d6']],
    [/permission|authori[sz]|tenant isolation/,['d12','d13']]
  ];
  return [...new Set(rules.filter(([test])=>test.test(query)).flatMap(([,ids])=>ids))];
}
function renderSearch(q){const text=q.toLowerCase().trim();let rows=[];if(!text)rows=pages.filter(p=>p[0]!=='saved').map(p=>({name:p[2],desc:'Open field guide section',page:p[0]}));else{rows=[...concepts.filter(c=>[c.name,c.desc,c.cat,c.example].join(' ').toLowerCase().includes(text)).map(c=>({name:c.name,desc:c.cat+' · '+c.level,id:c.id})),...compliance.filter(c=>c.slice(0,6).join(' ').toLowerCase().includes(text)).map(c=>({name:c[0],desc:c[1]+' · '+c[2],page:'compliance'})),...glossary.filter(r=>r.join(' ').toLowerCase().includes(text)).map(r=>({name:r[0],desc:r[1],page:'sources'})),...tests.filter(r=>r.join(' ').toLowerCase().includes(text)).map(r=>({name:r[0],desc:r[2],page:'qa'})),...pages.filter(p=>p[2].toLowerCase().includes(text)||p[0].includes(text)).map(p=>({name:p[2],desc:'Open section',page:p[0]}))];for(const id of problemMatches(text)){if(!rows.some(r=>r.id===id)){const c=concepts.find(c=>c.id===id);if(c)rows.push({name:c.name,desc:'Suggested concept · '+c.cat,id:c.id})}}if(/python|react|stack|database|library/.test(text))rows.push({name:'Tech stack decision guide',desc:'Products, libraries and tradeoffs',page:'stacks'});if(/atm|cash|money/.test(text))rows.push({name:'The ATM question',desc:'The limits of a prototype and the assurance gap',page:'risk'})}$('#search-results').innerHTML=`<div class="result-count">${text?rows.length+' MATCHES':'QUICK NAVIGATION'}</div>`+rows.slice(0,35).map(r=>`<button class="search-hit" ${r.id?`data-search-id="${r.id}"`:`data-search-page="${r.page}"`}><strong>${esc(r.name)}</strong><small>${esc(r.desc)}</small></button>`).join('')+(rows.length?'':'<p class="empty">No matches. Try a simpler term.</p>')}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}const b=e.target.closest('button');if(!b)return;if(b.dataset.example)showQAExample(b.dataset.example);if(b.dataset.detailTab)setDetailTab(b.dataset.detailTab,true);if(b.dataset.codeLang){exampleLanguage=b.dataset.codeLang;updateExample(true)}if(b.dataset.copyCode&&activeExampleId)copyText(codeExamples[activeExampleId][exampleLanguage]);if(b.dataset.detail)showDetail(b.dataset.detail);if(b.dataset.save)toggleSave(b.dataset.save);if(b.dataset.copyConcept)copyText(detailInfo(b.dataset.copyConcept).prompt);if(b.id==='close-detail')$('#detail-dialog').close();if(b.classList.contains('close-search'))$('#search-dialog').close();if(b.id==='open-search')openSearch();if(b.id==='mobile-menu')document.body.classList.toggle('menu-open');if(b.id==='print-top'||b.id==='print-checklist')window.print();if(b.dataset.tab){designTab=b.dataset.tab;designFilter='All';designQuery='';render()}if(b.dataset.filter){designFilter=b.dataset.filter;renderDesignBody()}if(b.dataset.domain){complianceFilter=b.dataset.domain;render()}if(b.dataset.pipe!==undefined){pipe=+b.dataset.pipe;renderPipe()}if(b.dataset.risk){risk=b.dataset.risk;renderRisk()}if(b.dataset.scenario){scenario=b.dataset.scenario;renderScenario()}if(b.id==='copy-yaml')copyText(yaml);if(b.id==='copy-task')copyText(taskPrompt);if(b.id==='copy-stack'){const{s,notes}=stackSpec();copyText(`Evaluate this suggested stack for my project; do not assume it is correct.\nProduct: ${s[0]}\nFrontend: ${s[1]}\nBackend: ${s[2]}\nData: ${s[3]}\nOperating model: ${s[4]}\nRationale: ${s[5]}\nTradeoff: ${s[6]}\nConstraints: ${notes.join(' ')}\nAsk for missing requirements, compare simpler alternatives, confirm maintained versions/licences and deployment fit, then propose a small proof of concept with acceptance tests.`)}if(b.id==='copy-checklist')copyText('Release evidence review — '+new Date().toISOString().slice(0,10)+'\nSelf-recorded review marks; not verified readiness.\n\n'+gateGroups.map(g=>g[0]+'\n'+g[1].map(r=>(checks[r[0]]?'[REVIEWED] ':'[OPEN] ')+r[1]+'\n  Evidence link / reviewer: __________').join('\n')).join('\n\n')+'\n\nUnresolved risks: __________\nRelease owner / decision: __________');if(b.id==='reset-checklist'){checks={};persist();document.querySelectorAll('[data-check]').forEach(c=>c.checked=false);updateChecks();toast('Review marks reset')}if(b.dataset.searchId){$('#search-dialog').close();showDetail(b.dataset.searchId)}if(b.dataset.searchPage){$('#search-dialog').close();if(b.dataset.searchPage==='compliance')complianceFilter='All';if(location.hash==='#'+b.dataset.searchPage)route();else location.hash=b.dataset.searchPage}});
document.addEventListener('input',e=>{if(e.target.id==='search-input')renderSearch(e.target.value);if(e.target.id==='design-query'){designQuery=e.target.value;const pos=e.target.selectionStart;renderDesignBody();$('#design-query').focus();$('#design-query').setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){checks[e.target.dataset.check]=e.target.checked;persist();updateChecks()}if(e.target.id.startsWith('stack-')){stackSelection[e.target.id.slice(6)]=e.target.value;renderStack()}if(e.target.id==='lifecycle-choice')renderLifecycle()});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-detail-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['guide','code','prompt'];let i=tabs.indexOf(activeDetailTab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;setDetailTab(tabs[i],true)}if(e.target.matches('[data-code-lang]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();exampleLanguage=e.key==='Home'?'python':e.key==='End'?'javascript':exampleLanguage==='python'?'javascript':'python';updateExample(true)}if(e.target.matches('[data-tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=['patterns','principles','architecture'];let ix=tabs.indexOf(designTab);ix=e.key==='Home'?0:e.key==='End'?2:(ix+(e.key==='ArrowRight'?1:2))%3;designTab=tabs[ix];designFilter='All';designQuery='';render();document.querySelector('[data-tab="'+designTab+'"]').focus()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search-dialog').open)openSearch()}if(e.key==='Escape')document.body.classList.remove('menu-open')});
for(const dlg of document.querySelectorAll('dialog'))dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});


function guidanceHTML(id,principle=false){
  const e=codeExamples[id];if(!e?.use||!e?.avoid)return '';
  return `<div class="usage-guide"><section class="use-guide"><span class="tiny">WHEN TO USE</span><p>${esc(e.use)}</p></section><section class="avoid-guide"><span class="tiny">${principle?'MISUSE TO AVOID':'WHEN NOT TO USE / PITFALLS'}</span><p>${esc(e.avoid)}</p></section></div>${principle?'<p class="principle-note">For principles, the second column describes misapplication—not a reason to abandon the principle.</p>':''}`;
}

let exampleLanguage='python',activeExampleId=null;
function exampleHTML(id){
  const e=codeExamples[id];if(!e)return '';
  const lang=exampleLanguage,template=e.verification==='template';
  return `<section class="code-example" id="code-example" aria-label="Code example"><div class="example-heading"><div><span class="tiny">SEE THE IDEA IN CODE</span><h3>Code example</h3></div><span class="tag ${template?'orange':''}">${template?'LOCAL TEST TEMPLATE':'RUNNABLE TEACHING SNIPPET'}</span></div><p class="example-summary">${esc(e.summary)}</p><div class="example-toolbar"><div role="tablist" aria-label="Example language">${['python','javascript'].map(l=>`<button type="button" role="tab" id="lang-${l}" aria-controls="example-panel" aria-selected="${l===lang}" tabindex="${l===lang?'0':'-1'}" data-code-lang="${l}" class="language-tab ${l===lang?'active':''}">${l==='python'?'Python':'JavaScript'}</button>`).join('')}</div><button class="btn small" data-copy-code="true" aria-label="Copy ${lang==='python'?'Python':'JavaScript'} example">Copy code ↗</button></div><div id="example-panel" role="tabpanel" aria-labelledby="lang-${lang}" tabindex="0"><p class="code-runtime">${lang==='python'?'Python 3.12 · save as example.py · python example.py':'Node.js 24 · save as example.cjs · node example.cjs'}${template?' · additional setup shown in the snippet':''}</p><pre><code>${esc(e[lang])}</code></pre></div><div class="expected-output"><span class="tiny">${template?'EXPECTED AFTER LOCAL SETUP':'EXPECTED OUTPUT'}</span><pre>${esc(e.output)}</pre></div><p class="example-limit"><b>Scope & limits:</b> ${esc(e.limit)}</p><details class="code-verification"><summary>Verification details</summary><div><p class="example-verification">${template?'Verification: both templates were syntax-checked. The Playwright programs were not executed here.':'Verification: both language snippets were executed and their output checked in Python 3.12 / Node.js 24.'} The page displays text only; it does not run these programs.</p></div></details></section>`;
}
function updateExample(focusTab=false){
  if(!activeExampleId)return;
  const previous=$('#code-example');if(!previous)return;
  previous.outerHTML=exampleHTML(activeExampleId);
  if(focusTab)document.querySelector('[data-code-lang="'+exampleLanguage+'"]').focus();
}

function showQAExample(id){
  if(!tests[Number(id.slice(1))]||!codeExamples[id])return;
  activeDetail={id,type:'qa'};activeDetailTab='guide';activeExampleId=id;
  renderDetail();if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
}
let activeDetail=null,activeDetailTab='guide';
function detailInfo(id){
  if(id.startsWith('t')){
    const r=tests[Number(id.slice(1))];
    return {id,name:r[0],cat:'Testing & QA',level:r[1],desc:r[2],example:r[3],caution:r[5],tools:r[4],kind:'qa',prompt:`Help me plan ${r[0].toLowerCase()} for this project. Identify the relevant requirements, boundaries and failure cases. Propose independently justified expected results and reproducible checks. Explain what this method cannot establish, and state any required setup. Do not treat generated tests as independent assurance.`};
  }
  return concepts.find(c=>c.id===id);
}
function detailPanelHTML(){
  const c=detailInfo(activeDetail.id);
  if(activeDetailTab==='code')return exampleHTML(c.id);
  if(activeDetailTab==='prompt')return `<div class="prompt-block"><h3>Ask your AI</h3><p>${esc(c.prompt)}</p><button class="btn primary" data-copy-concept="${c.id}">Copy prompt ↗</button></div><p class="prompt-help">Add your actual requirements, constraints and acceptance examples before using this prompt. Review the proposed change and its evidence.</p>`;
  return `${guidanceHTML(c.id,c.kind==='principles')}<section class="guide-example"><h3>${c.kind==='qa'?'A practical check':'A simple example'}</h3><p>${esc(c.example)}</p></section><details class="guide-cautions"><summary>Technical caveats${c.kind==='qa'?' & tools':''}</summary><div>${c.tools?`<p><b>Candidate tools:</b> ${esc(c.tools)}</p>`:''}<p>${esc(c.caution)}</p></div></details>`;
}
function renderDetail(){
  if(!activeDetail)return;
  const c=detailInfo(activeDetail.id),canSave=activeDetail.type==='concept';
  $('#detail-content').innerHTML=`<div class="detail-shell"><header class="detail-header"><span class="tag">${esc(c.cat)} / ${esc(c.level)}</span><div class="detail-actions">${canSave?`<button class="save ${saved.includes(c.id)?'active':''}" data-save="${c.id}" aria-label="${saved.includes(c.id)?'Unsave':'Save'} ${esc(c.name)}" aria-pressed="${saved.includes(c.id)}">${saved.includes(c.id)?'★':'☆'}</button>`:''}<button class="icon-btn" id="close-detail" aria-label="Close concept details">×</button></div></header><div class="detail-summary"><h2 id="detail-title">${esc(c.name)}</h2><p>${esc(c.desc)}</p></div><div class="detail-tabs" role="tablist" aria-label="Concept sections">${[['guide','Guide'],['code','Code'],['prompt','AI prompt']].map(([id,name])=>`<button type="button" id="detail-${id}" class="detail-tab ${id===activeDetailTab?'active':''}" data-detail-tab="${id}" role="tab" aria-selected="${id===activeDetailTab}" tabindex="${id===activeDetailTab?'0':'-1'}" aria-controls="detail-panel">${name}</button>`).join('')}</div><div id="detail-panel" class="detail-body" role="tabpanel" aria-labelledby="detail-${activeDetailTab}" tabindex="0">${detailPanelHTML()}</div></div>`;
}
function setDetailTab(tab,focusTab=false){
  if(!activeDetail||!['guide','code','prompt'].includes(tab))return;
  activeDetailTab=tab;
  const panel=$('#detail-panel');
  panel.innerHTML=detailPanelHTML();panel.setAttribute('aria-labelledby','detail-'+tab);panel.scrollTop=0;
  document.querySelectorAll('[data-detail-tab]').forEach(b=>{const current=b.dataset.detailTab===tab;b.classList.toggle('active',current);b.setAttribute('aria-selected',String(current));b.setAttribute('tabindex',current?'0':'-1')});
  if(focusTab)document.querySelector('[data-detail-tab="'+tab+'"]').focus();
}

window.addEventListener('hashchange',route);route();
